Projection.return_rows:
def return_rows():
    """The model point's return scenario: gross returns keyed by (subaccount, projected month)."""
    return data.scenario_table().loc[scenario_id()]

Projection.wd_pp_amount:
def wd_pp_amount():
    """The model point's constant monthly withdrawal amount."""
    return float(model_point()["wd_pp"])

Projection.corridor_override_m1:
def corridor_override_m1():
    """The model point's month-1 corridor factor override; blank (NaN) when there is none."""
    return model_point()["corridor_override_m1"]

Projection.has_corridor_override_m1:
def has_corridor_override_m1():
    """Whether the model point carries a month-1 corridor factor override (D64: the missing-value test, per policy)."""
    return not pd.isna(corridor_override_m1())

Projection.coi_rate_override_m1:
def coi_rate_override_m1():
    """The model point's month-1 COI rate override; blank (NaN) when there is none."""
    return model_point()["coi_rate_override_m1"]

Projection.has_coi_rate_override_m1:
def has_coi_rate_override_m1():
    """Whether the model point carries a month-1 COI rate override (D64: the missing-value test, per policy)."""
    return not pd.isna(coi_rate_override_m1())

Projection.surr_charge_init:
def surr_charge_init():
    """The schedule's initial surrender charge per $1,000 of face."""
    row = data.surr_charge_table().loc[surr_charge_id()]             # noqa: F821
    return float(row["sc_per_1000_init"])

Projection.surr_charge_runoff_years:
def surr_charge_runoff_years():
    """The schedule's run-off period in whole years."""
    row = data.surr_charge_table().loc[surr_charge_id()]             # noqa: F821
    return int(row["runoff_years"])
